use customer_behavior;
select * from dbo.CustomerData;


--Q1. what is the total revenue generated by male vs female customer?

select gender,sum(purchase_amount) as revenue 
from dbo.CustomerData 
group by gender;


--Q2. which customer used a discount but still spent more than average purchase amount?

select customer_id,purchase_amount from dbo.CustomerData
where discount_applied = 'Yes' and purchase_amount>= (select avg(purchase_amount) from dbo.CustomerData);


--Q3. which are the top 5 product with the highest avg review rating?

select top 5 
item_purchased,round(avg(review_rating),2) as 'average review rating' from dbo.CustomerData
group by item_purchased
order by avg(review_rating) desc ;


--Q4. Compare average purchase amounts between standard and express shopping.

select shipping_type,avg(purchase_amount)
from dbo.CustomerData
where shipping_type in ('Standard', 'Express')
group by shipping_type;



--Q5. Do subscribed spends more? compare average spend and total revenue 
-- between subscribes and non subscribes.

select subscription_status ,
round(avg(purchase_amount),2) as 'Avg spend',
sum(purchase_amount) as 'total revenue',
count(customer_id) as 'total customer'
from dbo.CustomerData
group by subscription_status
order by [total revenue],[Avg spend] desc;


--Q6. which 5 product have the highest percentage of purchase with discount applied?

select top 5 
item_purchased,
round(100 * sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*) ,2) as 'discount rate'
from dbo.CustomerData 
where discount_applied = 'Yes'
group by item_purchased
order by [discount rate] desc; 


--Q7. segment customer intoo new returning and loyal 
--based on their total number of previous purchase and show the count of each segment.

with customer_type as (
select customer_id, previous_purchases,
case 
	when previous_purchases = 1 then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
	else 'Loyal'
	end as customer_segment
from dbo.CustomerData
)

select customer_segment,count(*) as 'number of customer'
from customer_type
group by customer_segment;


--Q8. what are the top 3 most purchased product within each category.

with item_count as (
select category, item_purchased,
count(customer_id) as 'total_customer',
row_number() over(partition by category order by count(customer_id) desc) as 'item_rank'
from dbo.CustomerData
group by category,item_purchased
)

select item_rank,category,item_purchased,total_customer
from item_count
where item_rank <=3;


--Q9. Are customers who are repeat buyer ( more than 5 previous purchase) also likely to subscribe?

select subscription_status,
count(customer_id) as repeat_buyers
from dbo.CustomerData
where previous_purchases > 5
group by subscription_status;

--Q10. what is the revenue contribution of each age group?

select age_group,sum(purchase_amount) as total_revenue
from dbo.CustomerData
group by age_group
order by total_revenue desc;